1	import { QueryKeys } from '@/constants/query-keys';
2	import { SemSmartblockAlert } from '@/components/CRM/Broker/SemSmartblockAlert';
3	import { SemSmartblockSliderFrost } from '@/components/CRM/Broker/SemSmartblockSliderFrost';
4	import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
5	import { useIsGerencialOficioDetail } from '@/app/crm/gerencial-broker/_hooks/useIsGerencialOficioDetail';
6	import { gerencialOficioSectionStyle } from '@/app/crm/gerencial-broker/_components/shared/GerencialOficioSectionCard';
7	import { getSliderThumbOffsetStyle } from '@/functions/slider/getSliderThumbOffsetStyle';
8	import { formatCurrency } from '@/functions/formaters/formatCurrency';
9	import numberFormat from '@/functions/formaters/numberFormat';
10	import { sendToastMessage } from '@/functions/messages/toastMessage';
11	import { useIsLocalhost } from '@/lib/runtime/is-localhost';
12	import {
13	    isProposalSemSmartblock,
14	    SEM_SMARTBLOCK_CREATED_DESCRIPTION,
15	    SEM_SMARTBLOCK_TITLE,
16	} from '@/functions/propostas/is-proposal-sem-smartblock';
17	import { resolveOperationalProposta } from '@/functions/repactuacao/resolve-proposta-liquidacao-ref';
18	import { sleep } from '@/functions/timer/sleep';
19	import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
20	import { useSmartBlockHistoricalSuggestionsQuery } from '@/hooks/queries/smart-block-historical-suggestions';
21	import { OficioProposta } from '@/types/oficio';
22	import { cn } from '@/lib/utils';
23	import { saveProposalAndComission } from '@/services/BrokerServices';
24	import { useBrokerStore } from '@/store/useBroker';
25	import { SliderProposalValuesProps } from '@/types/broker';
26	import queryClient from '@/utils/queryClient';
27	import { useMutation, useQuery } from '@tanstack/react-query';
28	import { generateProposalFromExtrato } from '@/services/oficios';
29	import { getSmartBlockById } from '@/services/smart-blocks';
30	import { resolveBrokerPricingEngine } from '@/functions/finance/comissao-broker';
31	import { resolvePropostaSliderPricingInput } from '@/functions/repactuacao/resolve-proposta-slider-pricing';
32	import { LoaderCircle, PlusCircle, Sparkles } from 'lucide-react';
33	import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from 'react';
34	import dynamic from 'next/dynamic';
35	import { Button } from '../Button';
36	import { ErrorMessageBox } from '../ErrorMessage/ErrorMessageBox';
37	import { PropostaSliderSkeleton } from '../Skeletons/Broker/PropostaSliderSkeleton';
38	import { LockedSectionTooltip } from '../Tooltips/LockedSectionTooltip';
39	import { BROKER_REFETCH_DELAY_SECONDS, PERCENTAGE_FACTOR, SLIDER_STEP, TOOLTIP_DELAY_MS } from './constants';
40	
41	const BrokerProposalWizard = dynamic(
42	    () =>
43	        import('@/app/crm/broker/[id]/_components/BrokerProposalWizard').then(
44	            (mod) => ({ default: mod.BrokerProposalWizard }),
45	        ),
46	    {
47	        ssr: false,
48	        loading: () => (
49	            <div className="h-8 w-full animate-pulse rounded-md bg-muted" />
50	        ),
51	    },
52	);
53	
54	type SliderInputFieldTypes = 'proposal' | 'commissionBroker' | 'commissionCoordinator';
55	
56	interface BrokerSliderProps {
57	    isLocked?: boolean;
58	    overrideExtratoId?: string;
59	    initialProposalValue?: number;
60	    initialCommissionValue?: number;
61	}
62	
63	const BrokerSlider = ({ isLocked, overrideExtratoId, initialProposalValue, initialCommissionValue }: BrokerSliderProps) => {
64	    const isGerencialOficioDetail = useIsGerencialOficioDetail();
65	    const isLocalhost = useIsLocalhost();
66	    // store imports
67	    const storeExtratoId = useBrokerStore((store) => store.extratoId);
68	    const extratoId = overrideExtratoId || storeExtratoId;
69	
70	    // estados
71	    const [errorMessage, setErrorMessage] = useState<boolean>(false);
72	    const [savingProposalAndComission, startProposalTransition] = useTransition();
73	    const [sliderValues, setSliderValues] = useState<SliderProposalValuesProps>({
74	        proposal: 0,
75	        commissionBroker: 0,
76	        commissionCoordinator: 0,
77	    });
78	
79	    // Track if we've already applied the initial values from the chat context
80	    // so we don't overwrite user changes if the component re-renders
81	    const initialValuesAppliedRef = useRef<boolean>(false);
82	
83	    // ==================
84	    // # Data Hooks
85	    // ==================
86	    const {
87	        data: detailedExtratoData,
88	        isLoading: isLoadingExtratoData,
89	        isError: isErrorExtratoData,
90	    } = useQuery(useExtratoDataQueryOptions(extratoId));
91	
92	    // ==================
93	    // # Constants
94	    // ==================
95	    const sliderData = detailedExtratoData?.propostas?.find((p) => p.vigente);
96	
97	    const activeDue = detailedExtratoData?.due_diligence?.find(
98	        (due) => due.status !== 'CONCLUIDO' && due.status !== 'ARQUIVADA',
99	    );
100	
101	    const operationalProposal = useMemo(
102	        () =>
103	            resolveOperationalProposta(
104	                detailedExtratoData?.propostas,
105	                activeDue?.proposta_origem,
106	            ),
107	        [detailedExtratoData?.propostas, activeDue],
108	    );
109	
110	    const brandKitOwnerUserId = useMemo(() => {
111	        if (!isGerencialOficioDetail) return null;
112	
113	        const dueBroker = activeDue?.broker;
114	        if (dueBroker && typeof dueBroker === 'object' && dueBroker.id) {
115	            return String(dueBroker.id);
116	        }
117	
118	        const proposalCreator = operationalProposal?.criado_por;
119	        if (proposalCreator?.id) return String(proposalCreator.id);
120	
121	        const vigenteProposalCreator = sliderData?.criado_por;
122	        if (vigenteProposalCreator?.id) return String(vigenteProposalCreator.id);
123	
124	        const extratoCreator = detailedExtratoData?.criado_por;
125	        if (extratoCreator?.id) return String(extratoCreator.id);
126	
127	        return null;
128	    }, [isGerencialOficioDetail, activeDue, operationalProposal, sliderData, detailedExtratoData]);
129	
130	    const { data: suggestions } = useSmartBlockHistoricalSuggestionsQuery(
131	        isLocalhost ? sliderData?.smart_block : null,
132	    );
133	    const { data: smartBlock } = useQuery({
134	        queryKey: [QueryKeys.smartBlock.detail, sliderData?.smart_block],
135	        queryFn: () => getSmartBlockById(String(sliderData?.smart_block)),
136	        enabled: sliderData?.smart_block != null,
137	        refetchOnMount: 'always',
138	        staleTime: 0,
139	    });
140	    const isSemSmartblock = sliderData ? isProposalSemSmartblock(sliderData) : false;
141	    const isSliderInteractionLocked = Boolean(isLocked) || isSemSmartblock;
142	    const minCoordCommission: number = Number(sliderData?.comissao_minima_coordenador) || 0;
143	    const maxCoordCommission: number = Number(sliderData?.comissao_maxima_coordenador) || 0;
144	    const valorLiquidoExtrato = Number(detailedExtratoData?.valor_liquido_disponivel) || 0;
145	    // Régua efetiva: com repactuação V2 aberta vale a proposta_nova — SmartBlock
146	    // rematchado pro VL novo + exceção do broker já resolvidos no backend — não
147	    // a faixa congelada da proposta vigente.
148	    const pricingInput = useMemo(
149	        () =>
150	            resolvePropostaSliderPricingInput({
151	                dueDiligence: detailedExtratoData?.due_diligence,
152	                proposalData: sliderData,
153	                smartBlock,
154	                valorLiquidoExtrato,
155	            }),
156	        [detailedExtratoData?.due_diligence, sliderData, smartBlock, valorLiquidoExtrato],
157	    );
158	    const auxSliderValues: SliderProposalValuesProps = {
159	        proposal: pricingInput.propostaEscolhida,
160	        commissionBroker: pricingInput.comissaoEscolhida,
161	        commissionCoordinator: Number(sliderData?.comissao_escolhida_coordenador) || 0,
162	    };
163	    const sliderBounds = pricingInput.bounds;
164	    const minProposal: number = sliderBounds.minProposal;
165	    const maxProposal: number = sliderBounds.maxProposal;
166	    const pricingEngine = useMemo(
167	        () =>
168	            resolveBrokerPricingEngine({
169	                smartBlock: pricingInput.smartBlock,
170	                exceptionId: pricingInput.exceptionId,
171	                exceptionPricing: pricingInput.exceptionPricing,
172	                valorLiquido: pricingInput.valorLiquido,
173	                baseDesembolso: pricingInput.baseDesembolso,
174	                bounds: pricingInput.bounds,
175	                coordinatorBounds: { min: minCoordCommission, max: maxCoordCommission },
176	            }),
177	        [pricingInput, minCoordCommission, maxCoordCommission],
178	    );
179	    const commissionSliderBounds = pricingEngine.commissionSliderBounds;
180	    const calculateBrokerCommission = useCallback(
181	        (proposalCredor: number): number => pricingEngine.calculateCommissionForProposal(proposalCredor),
182	        [pricingEngine],
183	    );
184	    const resolveCoordinatorCommission = useCallback(
185	        (brokerCommission: number): number => pricingEngine.calculateCoordinatorCommission(brokerCommission),
186	        [pricingEngine],
187	    );
188	    const resolveBrokerCommissionFromCoordinatorValue = useCallback(
189	        (coordinatorCommission: number): number =>
190	            pricingEngine.calculateCommissionFromCoordinator(coordinatorCommission),
191	        [pricingEngine],
192	    );
193	
194	    const suggestedProposal = useMemo(() => {
195	        if (!maxProposal) return 0;
196	        const raw = suggestions?.suggested_proposal;
197	        if (raw == null || raw <= 0) return 0;
198	        return Math.min(Math.max(raw, minProposal), maxProposal);
199	    }, [suggestions, minProposal, maxProposal]);
200	
201	    const suggestedBrokerCommission = useMemo(() => {
202	        if (!suggestedProposal) return 0;
203	        return calculateBrokerCommission(suggestedProposal);
204	    }, [suggestedProposal, calculateBrokerCommission]);
205	
206	    const proposalSuggestionPct = useMemo(() => {
207	        const range = maxProposal - minProposal;
208	        if (range <= 0) return 0;
209	        return Math.max(0, Math.min(PERCENTAGE_FACTOR, ((suggestedProposal - minProposal) / range) * PERCENTAGE_FACTOR));
210	    }, [suggestedProposal, minProposal, maxProposal]);
211	
212	    const commissionSuggestionPct = useMemo(() => {
213	        const range = commissionSliderBounds.max - commissionSliderBounds.min;
214	        if (range <= 0) return 0;
215	        return Math.max(
216	            0,
217	            Math.min(
218	                PERCENTAGE_FACTOR,
219	                ((suggestedBrokerCommission - commissionSliderBounds.min) / range) * PERCENTAGE_FACTOR,
220	            ),
221	        );
222	    }, [suggestedBrokerCommission, commissionSliderBounds.min, commissionSliderBounds.max]);
223	
224	    const isSaveButtonDisabled = useMemo(() => {
225	        if (!sliderData) return true;
226	        return (
227	            pricingInput.propostaEscolhida === sliderValues.proposal &&
228	            pricingInput.comissaoEscolhida === sliderValues.commissionBroker
229	        );
230	    }, [sliderData, pricingInput, sliderValues]);
231	
232	    // refs
233	    const proposalRef = useRef<HTMLInputElement | null>(null);
234	    const commissionBrokerRef = useRef<HTMLInputElement | null>(null);
235	    const commissionCoordinatorRef = useRef<HTMLInputElement | null>(null);
236	    const isProposalButtonDisabled = useRef<boolean>(false);
237	
238	    // funções
239	    const handleProposalSliderChange = (value: string, sliderChange: boolean) => {
240	        const newProposalSliderValue = parseFloat(value);
241	
242	        if (newProposalSliderValue !== auxSliderValues.proposal) {
243	            isProposalButtonDisabled.current = false;
244	        } else {
245	            isProposalButtonDisabled.current = true;
246	        }
247	
248	        // Calcular a proporção em relação a proposta e ajustar a comissão
249	        const newCommissionBrokerSliderValue = calculateBrokerCommission(newProposalSliderValue);
250	
251	        const newCommissionCoordinatorSliderValue = resolveCoordinatorCommission(
252	            newCommissionBrokerSliderValue,
253	        );
254	        setSliderValues({
255	            proposal: newProposalSliderValue,
256	            commissionBroker: newCommissionBrokerSliderValue,
257	            commissionCoordinator: newCommissionCoordinatorSliderValue,
258	        });
259	
260	        if (commissionBrokerRef.current && proposalRef.current) {
261	            commissionBrokerRef.current.value = numberFormat(newCommissionBrokerSliderValue);
262	            // if (commissionCoordinatorRef.current) {
263	            //     commissionCoordinatorRef.current.value = numberFormat(
264	            //         newCommissionCoordinatorSliderValue,
265	            //     );
266	            // }
267	            if (sliderChange) {
268	                proposalRef.current.value = numberFormat(newProposalSliderValue);
269	            }
270	        }
271	    };
272	
273	    const handleComissionBrokerSliderChange = (value: string, sliderChange: boolean) => {
274	        const newCommissionBrokerSliderValue = parseFloat(value);
275	
276	        if (newCommissionBrokerSliderValue !== auxSliderValues.commissionBroker) {
277	            isProposalButtonDisabled.current = false;
278	        } else {
279	            isProposalButtonDisabled.current = true;
280	        }
281	
282	        const newProposalSliderValue = pricingEngine.calculateProposalForCommission(
283	            newCommissionBrokerSliderValue,
284	        );
285	        const adjustedCommissionBroker = calculateBrokerCommission(newProposalSliderValue);
286	        const newCommissionCoordinatorSliderValue =
287	            resolveCoordinatorCommission(adjustedCommissionBroker);
288	
289	        setSliderValues({
290	            proposal: newProposalSliderValue,
291	            commissionBroker: adjustedCommissionBroker,
292	            commissionCoordinator: newCommissionCoordinatorSliderValue,
293	        });
294	
295	        if (proposalRef.current && commissionBrokerRef.current) {
296	            proposalRef.current.value = numberFormat(newProposalSliderValue);
297	            if (sliderChange) {
298	                commissionBrokerRef.current.value = numberFormat(adjustedCommissionBroker);
299	            }
300	        }
301	    };
302	
303	    const handleComissionCoordinatorSliderChange = (value: string, sliderChange: boolean) => {
304	        const newComissionCoordinatorSliderValue = parseFloat(value);
305	
306	        if (newComissionCoordinatorSliderValue !== auxSliderValues.commissionCoordinator) {
307	            isProposalButtonDisabled.current = false;
308	        } else {
309	            isProposalButtonDisabled.current = true;
310	        }
311	
312	        const newCommissionBrokerSliderValue = resolveBrokerCommissionFromCoordinatorValue(
313	            newComissionCoordinatorSliderValue,
314	        );
315	
316	        const newProposalSliderValue = pricingEngine.calculateProposalForCommission(
317	            newCommissionBrokerSliderValue,
318	        );
319	        const adjustedCommissionBroker = calculateBrokerCommission(newProposalSliderValue);
320	
321	        setSliderValues({
322	            proposal: newProposalSliderValue,
323	            commissionBroker: adjustedCommissionBroker,
324	            commissionCoordinator: newComissionCoordinatorSliderValue,
325	        });
326	
327	        if (
328	            proposalRef.current &&
329	            commissionBrokerRef.current &&
330	            commissionCoordinatorRef.current
331	        ) {
332	            proposalRef.current.value = numberFormat(newProposalSliderValue);
333	            commissionBrokerRef.current.value = numberFormat(adjustedCommissionBroker);
334	            if (sliderChange) {
335	                commissionCoordinatorRef.current.value = numberFormat(
336	                    newComissionCoordinatorSliderValue,
337	                );
338	            }
339	        }
340	    };
341	
342	    const changeInputValues = (inputField: SliderInputFieldTypes, value: string) => {
343	        const rawValue = value
344	            .replace(/R\$\s*/g, '')
345	            .replaceAll('.', '')
346	            .replaceAll(',', '.');
347	
348	        const numericalValue = parseFloat(rawValue);
349	
350	        switch (inputField) {
351	            case 'proposal':
352	                if (
353	                    numericalValue >= (minProposal || 0) &&
354	                    numericalValue <= (maxProposal || 0) &&
355	                    !isNaN(numericalValue) &&
356	                    numericalValue !== auxSliderValues.proposal
357	                ) {
358	                    isProposalButtonDisabled.current = false;
359	                } else {
360	                    isProposalButtonDisabled.current = true;
361	                }
362	
363	                if (
364	                    numericalValue < (minProposal || 0) ||
365	                    numericalValue > (maxProposal || 0) ||
366	                    isNaN(numericalValue)
367	                ) {
368	                    setErrorMessage(true);
369	                    return;
370	                } else {
371	                    setErrorMessage(false);
372	                }
373	
374	                setSliderValues((old) => {
375	                    return {
376	                        ...old,
377	                        proposal: parseFloat(rawValue),
378	                    };
379	                });
380	                handleProposalSliderChange(rawValue, false);
381	                break;
382	
383	            case 'commissionBroker':
384	                if (
385	                    numericalValue >= (commissionSliderBounds.min || 0) &&
386	                    numericalValue <= (commissionSliderBounds.max || 0) &&
387	                    !isNaN(numericalValue) &&
388	                    numericalValue !== auxSliderValues.commissionBroker
389	                ) {
390	                    isProposalButtonDisabled.current = false;
391	                } else {
392	                    isProposalButtonDisabled.current = true;
393	                }
394	
395	                if (
396	                    numericalValue < (commissionSliderBounds.min || 0) ||
397	                    numericalValue > (commissionSliderBounds.max || 0) ||
398	                    isNaN(numericalValue)
399	                ) {
400	                    setErrorMessage(true);
401	                    return;
402	                } else {
403	                    setErrorMessage(false);
404	                }
405	
406	                setSliderValues((old) => {
407	                    return {
408	                        ...old,
409	                        commissionBroker: parseFloat(rawValue),
410	                    };
411	                });
412	                handleComissionBrokerSliderChange(rawValue, false);
413	                break;
414	
415	            case 'commissionCoordinator':
416	                if (
417	                    numericalValue < (minCoordCommission || 0) ||
418	                    numericalValue > (maxCoordCommission || 0) ||
419	                    (isNaN(numericalValue) &&
420	                        numericalValue !== auxSliderValues.commissionCoordinator)
421	                ) {
422	                    setErrorMessage(true);
423	                    return;
424	                } else {
425	                    setErrorMessage(false);
426	                }
427	
428	                setSliderValues((old) => {
429	                    return {
430	                        ...old,
431	                        commissionCoordinator: parseFloat(rawValue),
432	                    };
433	                });
434	                handleComissionCoordinatorSliderChange(rawValue, false);
435	                break;
436	
437	            default:
438	                break;
439	        }
440	    };
441	
442	    const handleProposalAndCommission = () => {
443	        startProposalTransition(async () => {
444	            if (!sliderData) return;
445	
446	            try {
447	                await saveProposalAndComission(sliderData.uuid, sliderValues);
448	                sendToastMessage({
449	                    title: 'Proposta e comissão salvas com sucesso!',
450	                    type: 'success',
451	                });
452	                await handleRefetchData();
453	            } catch (error) {
454	                console.error(error);
455	                sendToastMessage({ title: 'Erro ao salvar proposta e comissão!', type: 'error' });
456	            }
457	        });
458	    };
459	
460	    const handleRefetchData = async () => {
461	        await sleep(BROKER_REFETCH_DELAY_SECONDS);
462	        const updatingToastId = sendToastMessage({
463	            title: 'Atualizando dados da proposta.',
464	            type: 'loading',
465	        });
466	
467	        try {
468	            await Promise.all([
469	                queryClient.invalidateQueries({
470	                    queryKey: [QueryKeys.propostas.vigente, sliderData?.uuid],
471	                }),
472	                queryClient.invalidateQueries({
473	                    queryKey: [QueryKeys.oficios.proposalList, extratoId],
474	                }),
475	            ]);
476	            sendToastMessage({
477	                title: 'Dados da proposta atualizados com sucesso!',
478	                type: 'success',
479	                previousToastId: updatingToastId,
480	            });
481	        } catch (error) {
482	            console.error('Erro ao atualizar dados:', error);
483	            sendToastMessage({
484	                title: 'Erro ao atualizar.',
485	                description: 'Oferta salva, porém não foi possível atualizar os dados da proposta.',
486	                type: 'error',
487	                previousToastId: updatingToastId,
488	            });
489	            throw error;
490	        }
491	    };
492	
493	    /**
494	     * Define so valores dos sliders de acordo com os valores
495	     * de proposta/comissão do oficio carregado OU valores iniciais do chat
496	     */
497	    useEffect(() => {
498	        if (!sliderData) {
499	            return;
500	        }
501	
502	        // Em repactuação, as escolhidas efetivas são as da proposta_nova.
503	        let initialProposal = pricingInput.propostaEscolhida;
504	        let initialCommission = pricingEngine.resolveCommissionForDisplay(
505	            initialProposal,
506	            pricingInput.comissaoEscolhida,
507	        );
508	        let initialCoordinator = Number(sliderData.comissao_escolhida_coordenador) || 0;
509	
510	        if (initialProposalValue !== undefined && !initialValuesAppliedRef.current) {
511	            initialProposal = initialProposalValue;
512	            if (initialCommissionValue !== undefined) {
513	                initialCommission = initialCommissionValue;
514	            } else {
515	                initialCommission = pricingEngine.resolveCommissionForDisplay(
516	                    initialProposal,
517	                    pricingInput.comissaoEscolhida,
518	                );
519	            }
520	            initialCoordinator = resolveCoordinatorCommission(initialCommission);
521	            initialValuesAppliedRef.current = true;
522	        } else if (minCoordCommission > 0 && maxCoordCommission > 0) {
523	            initialCoordinator = resolveCoordinatorCommission(initialCommission);
524	        }
525	
526	        setSliderValues({
527	            proposal: initialProposal,
528	            commissionBroker: initialCommission,
529	            commissionCoordinator: initialCoordinator,
530	        });
531	
532	        if (proposalRef.current && commissionBrokerRef.current) {
533	            proposalRef.current.value = numberFormat(initialProposal);
534	            commissionBrokerRef.current.value = numberFormat(initialCommission);
535	
536	            if (commissionCoordinatorRef.current) {
537	                commissionCoordinatorRef.current.value = numberFormat(initialCoordinator);
538	            }
539	        }
540	    }, [
541	        sliderData,
542	        initialProposalValue,
543	        initialCommissionValue,
544	        pricingEngine,
545	        pricingInput,
546	        minCoordCommission,
547	        maxCoordCommission,
548	        resolveCoordinatorCommission,
549	    ]);
550	
551	    const createProposalMutation = useMutation({
552	        mutationFn: () => generateProposalFromExtrato(extratoId as string),
553	        onError: () => sendToastMessage({ title: 'Erro ao criar proposta.', type: 'error' }),
554	        onSuccess: async (data: OficioProposta) => {
555	            const isSemSmartblock = Number(data?.proposta_maxima ?? 0) === 0;
556	            sendToastMessage({
557	                type: isSemSmartblock ? 'warning' : 'success',
558	                title: isSemSmartblock ? SEM_SMARTBLOCK_TITLE : 'Proposta criada com sucesso!',
559	                description: isSemSmartblock ? SEM_SMARTBLOCK_CREATED_DESCRIPTION : undefined,
560	            });
