import { QueryKeys } from '@/constants/query-keys';
import { SemSmartblockAlert } from '@/components/CRM/Broker/SemSmartblockAlert';
import { SemSmartblockSliderFrost } from '@/components/CRM/Broker/SemSmartblockSliderFrost';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { useIsGerencialOficioDetail } from '@/app/crm/gerencial-broker/_hooks/useIsGerencialOficioDetail';
import { gerencialOficioSectionStyle } from '@/app/crm/gerencial-broker/_components/shared/GerencialOficioSectionCard';
import { getSliderThumbOffsetStyle } from '@/functions/slider/getSliderThumbOffsetStyle';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import numberFormat from '@/functions/formaters/numberFormat';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { useIsLocalhost } from '@/lib/runtime/is-localhost';
import {
    isProposalSemSmartblock,
    SEM_SMARTBLOCK_CREATED_DESCRIPTION,
    SEM_SMARTBLOCK_TITLE,
} from '@/functions/propostas/is-proposal-sem-smartblock';
import { resolveOperationalProposta } from '@/functions/repactuacao/resolve-proposta-liquidacao-ref';
import { sleep } from '@/functions/timer/sleep';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { useSmartBlockHistoricalSuggestionsQuery } from '@/hooks/queries/smart-block-historical-suggestions';
import { OficioProposta } from '@/types/oficio';
import { cn } from '@/lib/utils';
import { saveProposalAndComission } from '@/services/BrokerServices';
import { useBrokerStore } from '@/store/useBroker';
import { SliderProposalValuesProps } from '@/types/broker';
import queryClient from '@/utils/queryClient';
import { useMutation, useQuery } from '@tanstack/react-query';
import { generateProposalFromExtrato } from '@/services/oficios';
import { getSmartBlockById } from '@/services/smart-blocks';
import { resolveBrokerPricingEngine } from '@/functions/finance/comissao-broker';
import { resolvePropostaSliderPricingInput } from '@/functions/repactuacao/resolve-proposta-slider-pricing';
import { LoaderCircle, PlusCircle, Sparkles } from 'lucide-react';
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from 'react';
import dynamic from 'next/dynamic';
import { Button } from '../Button';
import { ErrorMessageBox } from '../ErrorMessage/ErrorMessageBox';
import { PropostaSliderSkeleton } from '../Skeletons/Broker/PropostaSliderSkeleton';
import { LockedSectionTooltip } from '../Tooltips/LockedSectionTooltip';
import { BROKER_REFETCH_DELAY_SECONDS, PERCENTAGE_FACTOR, SLIDER_STEP, TOOLTIP_DELAY_MS } from './constants';

const BrokerProposalWizard = dynamic(
    () =>
        import('@/app/crm/broker/[id]/_components/BrokerProposalWizard').then(
            (mod) => ({ default: mod.BrokerProposalWizard }),
        ),
    {
        ssr: false,
        loading: () => (
            <div className="h-8 w-full animate-pulse rounded-md bg-muted" />
        ),
    },
);

type SliderInputFieldTypes = 'proposal' | 'commissionBroker' | 'commissionCoordinator';

interface BrokerSliderProps {
    isLocked?: boolean;
    overrideExtratoId?: string;
    initialProposalValue?: number;
    initialCommissionValue?: number;
}

const BrokerSlider = ({ isLocked, overrideExtratoId, initialProposalValue, initialCommissionValue }: BrokerSliderProps) => {
    const isGerencialOficioDetail = useIsGerencialOficioDetail();
    const isLocalhost = useIsLocalhost();
    // store imports
    const storeExtratoId = useBrokerStore((store) => store.extratoId);
    const extratoId = overrideExtratoId || storeExtratoId;

    // estados
    const [errorMessage, setErrorMessage] = useState<boolean>(false);
    const [savingProposalAndComission, startProposalTransition] = useTransition();
    const [sliderValues, setSliderValues] = useState<SliderProposalValuesProps>({
        proposal: 0,
        commissionBroker: 0,
        commissionCoordinator: 0,
    });

    // Track if we've already applied the initial values from the chat context
    // so we don't overwrite user changes if the component re-renders
    const initialValuesAppliedRef = useRef<boolean>(false);

    // ==================
    // # Data Hooks
    // ==================
    const {
        data: detailedExtratoData,
        isLoading: isLoadingExtratoData,
        isError: isErrorExtratoData,
    } = useQuery(useExtratoDataQueryOptions(extratoId));

    // ==================
    // # Constants
    // ==================
    const sliderData = detailedExtratoData?.propostas?.find((p) => p.vigente);

    const activeDue = detailedExtratoData?.due_diligence?.find(
        (due) => due.status !== 'CONCLUIDO' && due.status !== 'ARQUIVADA',
    );

    const operationalProposal = useMemo(
        () =>
            resolveOperationalProposta(
                detailedExtratoData?.propostas,
                activeDue?.proposta_origem,
            ),
        [detailedExtratoData?.propostas, activeDue],
    );

    const brandKitOwnerUserId = useMemo(() => {
        if (!isGerencialOficioDetail) return null;

        const dueBroker = activeDue?.broker;
        if (dueBroker && typeof dueBroker === 'object' && dueBroker.id) {
            return String(dueBroker.id);
        }

        const proposalCreator = operationalProposal?.criado_por;
        if (proposalCreator?.id) return String(proposalCreator.id);

        const vigenteProposalCreator = sliderData?.criado_por;
        if (vigenteProposalCreator?.id) return String(vigenteProposalCreator.id);

        const extratoCreator = detailedExtratoData?.criado_por;
        if (extratoCreator?.id) return String(extratoCreator.id);

        return null;
    }, [isGerencialOficioDetail, activeDue, operationalProposal, sliderData, detailedExtratoData]);

    const { data: suggestions } = useSmartBlockHistoricalSuggestionsQuery(
        isLocalhost ? sliderData?.smart_block : null,
    );
    const { data: smartBlock } = useQuery({
        queryKey: [QueryKeys.smartBlock.detail, sliderData?.smart_block],
        queryFn: () => getSmartBlockById(String(sliderData?.smart_block)),
        enabled: sliderData?.smart_block != null,
        refetchOnMount: 'always',
        staleTime: 0,
    });
    const isSemSmartblock = sliderData ? isProposalSemSmartblock(sliderData) : false;
    const isSliderInteractionLocked = Boolean(isLocked) || isSemSmartblock;
    const minCoordCommission: number = Number(sliderData?.comissao_minima_coordenador) || 0;
    const maxCoordCommission: number = Number(sliderData?.comissao_maxima_coordenador) || 0;
    const valorLiquidoExtrato = Number(detailedExtratoData?.valor_liquido_disponivel) || 0;
    // Régua efetiva: com repactuação V2 aberta vale a proposta_nova — SmartBlock
    // rematchado pro VL novo + exceção do broker já resolvidos no backend — não
    // a faixa congelada da proposta vigente.
    const pricingInput = useMemo(
        () =>
            resolvePropostaSliderPricingInput({
                dueDiligence: detailedExtratoData?.due_diligence,
                proposalData: sliderData,
                smartBlock,
                valorLiquidoExtrato,
            }),
        [detailedExtratoData?.due_diligence, sliderData, smartBlock, valorLiquidoExtrato],
    );
    const auxSliderValues: SliderProposalValuesProps = {
        proposal: pricingInput.propostaEscolhida,
        commissionBroker: pricingInput.comissaoEscolhida,
        commissionCoordinator: Number(sliderData?.comissao_escolhida_coordenador) || 0,
    };
    const sliderBounds = pricingInput.bounds;
    const minProposal: number = sliderBounds.minProposal;
    const maxProposal: number = sliderBounds.maxProposal;
    const pricingEngine = useMemo(
        () =>
            resolveBrokerPricingEngine({
                smartBlock: pricingInput.smartBlock,
                exceptionId: pricingInput.exceptionId,
                exceptionPricing: pricingInput.exceptionPricing,
                valorLiquido: pricingInput.valorLiquido,
                baseDesembolso: pricingInput.baseDesembolso,
                bounds: pricingInput.bounds,
                coordinatorBounds: { min: minCoordCommission, max: maxCoordCommission },
            }),
        [pricingInput, minCoordCommission, maxCoordCommission],
    );
    const commissionSliderBounds = pricingEngine.commissionSliderBounds;
    const calculateBrokerCommission = useCallback(
        (proposalCredor: number): number => pricingEngine.calculateCommissionForProposal(proposalCredor),
        [pricingEngine],
    );
    const resolveCoordinatorCommission = useCallback(
        (brokerCommission: number): number => pricingEngine.calculateCoordinatorCommission(brokerCommission),
        [pricingEngine],
    );
    const resolveBrokerCommissionFromCoordinatorValue = useCallback(
        (coordinatorCommission: number): number =>
            pricingEngine.calculateCommissionFromCoordinator(coordinatorCommission),
        [pricingEngine],
    );

    const suggestedProposal = useMemo(() => {
        if (!maxProposal) return 0;
        const raw = suggestions?.suggested_proposal;
        if (raw == null || raw <= 0) return 0;
        return Math.min(Math.max(raw, minProposal), maxProposal);
    }, [suggestions, minProposal, maxProposal]);

    const suggestedBrokerCommission = useMemo(() => {
        if (!suggestedProposal) return 0;
        return calculateBrokerCommission(suggestedProposal);
    }, [suggestedProposal, calculateBrokerCommission]);

    const proposalSuggestionPct = useMemo(() => {
        const range = maxProposal - minProposal;
        if (range <= 0) return 0;
        return Math.max(0, Math.min(PERCENTAGE_FACTOR, ((suggestedProposal - minProposal) / range) * PERCENTAGE_FACTOR));
    }, [suggestedProposal, minProposal, maxProposal]);

    const commissionSuggestionPct = useMemo(() => {
        const range = commissionSliderBounds.max - commissionSliderBounds.min;
        if (range <= 0) return 0;
        return Math.max(
            0,
            Math.min(
                PERCENTAGE_FACTOR,
                ((suggestedBrokerCommission - commissionSliderBounds.min) / range) * PERCENTAGE_FACTOR,
            ),
        );
    }, [suggestedBrokerCommission, commissionSliderBounds.min, commissionSliderBounds.max]);

    const isSaveButtonDisabled = useMemo(() => {
        if (!sliderData) return true;
        return (
            pricingInput.propostaEscolhida === sliderValues.proposal &&
            pricingInput.comissaoEscolhida === sliderValues.commissionBroker
        );
    }, [sliderData, pricingInput, sliderValues]);

    // refs
    const proposalRef = useRef<HTMLInputElement | null>(null);
    const commissionBrokerRef = useRef<HTMLInputElement | null>(null);
    const commissionCoordinatorRef = useRef<HTMLInputElement | null>(null);
    const isProposalButtonDisabled = useRef<boolean>(false);

    // funções
    const handleProposalSliderChange = (value: string, sliderChange: boolean) => {
        const newProposalSliderValue = parseFloat(value);

        if (newProposalSliderValue !== auxSliderValues.proposal) {
            isProposalButtonDisabled.current = false;
        } else {
            isProposalButtonDisabled.current = true;
        }

        // Calcular a proporção em relação a proposta e ajustar a comissão
        const newCommissionBrokerSliderValue = calculateBrokerCommission(newProposalSliderValue);

        const newCommissionCoordinatorSliderValue = resolveCoordinatorCommission(
            newCommissionBrokerSliderValue,
        );
        setSliderValues({
            proposal: newProposalSliderValue,
            commissionBroker: newCommissionBrokerSliderValue,
            commissionCoordinator: newCommissionCoordinatorSliderValue,
        });

        if (commissionBrokerRef.current && proposalRef.current) {
            commissionBrokerRef.current.value = numberFormat(newCommissionBrokerSliderValue);
            // if (commissionCoordinatorRef.current) {
            //     commissionCoordinatorRef.current.value = numberFormat(
            //         newCommissionCoordinatorSliderValue,
            //     );
            // }
            if (sliderChange) {
                proposalRef.current.value = numberFormat(newProposalSliderValue);
            }
        }
    };

    const handleComissionBrokerSliderChange = (value: string, sliderChange: boolean) => {
        const newCommissionBrokerSliderValue = parseFloat(value);

        if (newCommissionBrokerSliderValue !== auxSliderValues.commissionBroker) {
            isProposalButtonDisabled.current = false;
        } else {
            isProposalButtonDisabled.current = true;
        }

        const newProposalSliderValue = pricingEngine.calculateProposalForCommission(
            newCommissionBrokerSliderValue,
        );
        const adjustedCommissionBroker = calculateBrokerCommission(newProposalSliderValue);
        const newCommissionCoordinatorSliderValue =
            resolveCoordinatorCommission(adjustedCommissionBroker);

        setSliderValues({
            proposal: newProposalSliderValue,
            commissionBroker: adjustedCommissionBroker,
            commissionCoordinator: newCommissionCoordinatorSliderValue,
        });

        if (proposalRef.current && commissionBrokerRef.current) {
            proposalRef.current.value = numberFormat(newProposalSliderValue);
            if (sliderChange) {
                commissionBrokerRef.current.value = numberFormat(adjustedCommissionBroker);
            }
        }
    };

    const handleComissionCoordinatorSliderChange = (value: string, sliderChange: boolean) => {
        const newComissionCoordinatorSliderValue = parseFloat(value);

        if (newComissionCoordinatorSliderValue !== auxSliderValues.commissionCoordinator) {
            isProposalButtonDisabled.current = false;
        } else {
            isProposalButtonDisabled.current = true;
        }

        const newCommissionBrokerSliderValue = resolveBrokerCommissionFromCoordinatorValue(
            newComissionCoordinatorSliderValue,
        );

        const newProposalSliderValue = pricingEngine.calculateProposalForCommission(
            newCommissionBrokerSliderValue,
        );
        const adjustedCommissionBroker = calculateBrokerCommission(newProposalSliderValue);

        setSliderValues({
            proposal: newProposalSliderValue,
            commissionBroker: adjustedCommissionBroker,
            commissionCoordinator: newComissionCoordinatorSliderValue,
        });

        if (
            proposalRef.current &&
            commissionBrokerRef.current &&
            commissionCoordinatorRef.current
        ) {
            proposalRef.current.value = numberFormat(newProposalSliderValue);
            commissionBrokerRef.current.value = numberFormat(adjustedCommissionBroker);
            if (sliderChange) {
                commissionCoordinatorRef.current.value = numberFormat(
                    newComissionCoordinatorSliderValue,
                );
            }
        }
    };

    const changeInputValues = (inputField: SliderInputFieldTypes, value: string) => {
        const rawValue = value
            .replace(/R\$\s*/g, '')
            .replaceAll('.', '')
            .replaceAll(',', '.');

        const numericalValue = parseFloat(rawValue);

        switch (inputField) {
            case 'proposal':
                if (
                    numericalValue >= (minProposal || 0) &&
                    numericalValue <= (maxProposal || 0) &&
                    !isNaN(numericalValue) &&
                    numericalValue !== auxSliderValues.proposal
                ) {
                    isProposalButtonDisabled.current = false;
                } else {
                    isProposalButtonDisabled.current = true;
                }

                if (
                    numericalValue < (minProposal || 0) ||
                    numericalValue > (maxProposal || 0) ||
                    isNaN(numericalValue)
                ) {
                    setErrorMessage(true);
                    return;
                } else {
                    setErrorMessage(false);
                }

                setSliderValues((old) => {
                    return {
                        ...old,
                        proposal: parseFloat(rawValue),
                    };
                });
                handleProposalSliderChange(rawValue, false);
                break;

            case 'commissionBroker':
                if (
                    numericalValue >= (commissionSliderBounds.min || 0) &&
                    numericalValue <= (commissionSliderBounds.max || 0) &&
                    !isNaN(numericalValue) &&
                    numericalValue !== auxSliderValues.commissionBroker
                ) {
                    isProposalButtonDisabled.current = false;
                } else {
                    isProposalButtonDisabled.current = true;
                }

                if (
                    numericalValue < (commissionSliderBounds.min || 0) ||
                    numericalValue > (commissionSliderBounds.max || 0) ||
                    isNaN(numericalValue)
                ) {
                    setErrorMessage(true);
                    return;
                } else {
                    setErrorMessage(false);
                }

                setSliderValues((old) => {
                    return {
                        ...old,
                        commissionBroker: parseFloat(rawValue),
                    };
                });
                handleComissionBrokerSliderChange(rawValue, false);
                break;

            case 'commissionCoordinator':
                if (
                    numericalValue < (minCoordCommission || 0) ||
                    numericalValue > (maxCoordCommission || 0) ||
                    (isNaN(numericalValue) &&
                        numericalValue !== auxSliderValues.commissionCoordinator)
                ) {
                    setErrorMessage(true);
                    return;
                } else {
                    setErrorMessage(false);
                }

                setSliderValues((old) => {
                    return {
                        ...old,
                        commissionCoordinator: parseFloat(rawValue),
                    };
                });
                handleComissionCoordinatorSliderChange(rawValue, false);
                break;

            default:
                break;
        }
    };

    const handleProposalAndCommission = () => {
        startProposalTransition(async () => {
            if (!sliderData) return;

            try {
                await saveProposalAndComission(sliderData.uuid, sliderValues);
                sendToastMessage({
                    title: 'Proposta e comissão salvas com sucesso!',
                    type: 'success',
                });
                await handleRefetchData();
            } catch (error) {
                console.error(error);
                sendToastMessage({ title: 'Erro ao salvar proposta e comissão!', type: 'error' });
            }
        });
    };

    const handleRefetchData = async () => {
        await sleep(BROKER_REFETCH_DELAY_SECONDS);
        const updatingToastId = sendToastMessage({
            title: 'Atualizando dados da proposta.',
            type: 'loading',
        });

        try {
            await Promise.all([
                queryClient.invalidateQueries({
                    queryKey: [QueryKeys.propostas.vigente, sliderData?.uuid],
                }),
                queryClient.invalidateQueries({
                    queryKey: [QueryKeys.oficios.proposalList, extratoId],
                }),
            ]);
            sendToastMessage({
                title: 'Dados da proposta atualizados com sucesso!',
                type: 'success',
                previousToastId: updatingToastId,
            });
        } catch (error) {
            console.error('Erro ao atualizar dados:', error);
            sendToastMessage({
                title: 'Erro ao atualizar.',
                description: 'Oferta salva, porém não foi possível atualizar os dados da proposta.',
                type: 'error',
                previousToastId: updatingToastId,
            });
            throw error;
        }
    };

    /**
     * Define so valores dos sliders de acordo com os valores
     * de proposta/comissão do oficio carregado OU valores iniciais do chat
     */
    useEffect(() => {
        if (!sliderData) {
            return;
        }

        // Em repactuação, as escolhidas efetivas são as da proposta_nova.
        let initialProposal = pricingInput.propostaEscolhida;
        let initialCommission = pricingEngine.resolveCommissionForDisplay(
            initialProposal,
            pricingInput.comissaoEscolhida,
        );
        let initialCoordinator = Number(sliderData.comissao_escolhida_coordenador) || 0;

        if (initialProposalValue !== undefined && !initialValuesAppliedRef.current) {
            initialProposal = initialProposalValue;
            if (initialCommissionValue !== undefined) {
                initialCommission = initialCommissionValue;
            } else {
                initialCommission = pricingEngine.resolveCommissionForDisplay(
                    initialProposal,
                    pricingInput.comissaoEscolhida,
                );
            }
            initialCoordinator = resolveCoordinatorCommission(initialCommission);
            initialValuesAppliedRef.current = true;
        } else if (minCoordCommission > 0 && maxCoordCommission > 0) {
            initialCoordinator = resolveCoordinatorCommission(initialCommission);
        }

        setSliderValues({
            proposal: initialProposal,
            commissionBroker: initialCommission,
            commissionCoordinator: initialCoordinator,
        });

        if (proposalRef.current && commissionBrokerRef.current) {
            proposalRef.current.value = numberFormat(initialProposal);
            commissionBrokerRef.current.value = numberFormat(initialCommission);

            if (commissionCoordinatorRef.current) {
                commissionCoordinatorRef.current.value = numberFormat(initialCoordinator);
            }
        }
    }, [
        sliderData,
        initialProposalValue,
        initialCommissionValue,
        pricingEngine,
        pricingInput,
        minCoordCommission,
        maxCoordCommission,
        resolveCoordinatorCommission,
    ]);

    const createProposalMutation = useMutation({
        mutationFn: () => generateProposalFromExtrato(extratoId as string),
        onError: () => sendToastMessage({ title: 'Erro ao criar proposta.', type: 'error' }),
        onSuccess: async (data: OficioProposta) => {
            const isSemSmartblock = Number(data?.proposta_maxima ?? 0) === 0;
            sendToastMessage({
                type: isSemSmartblock ? 'warning' : 'success',
                title: isSemSmartblock ? SEM_SMARTBLOCK_TITLE : 'Proposta criada com sucesso!',
                description: isSemSmartblock ? SEM_SMARTBLOCK_CREATED_DESCRIPTION : undefined,
            });
            await queryClient.invalidateQueries({ queryKey: [QueryKeys.oficios.item] });
        },
    });

    if (isLoadingExtratoData) {
        return <PropostaSliderSkeleton />;
    }

    if (isErrorExtratoData) {
        return <ErrorMessageBox className="xl:col-span-4" />;
    }

    return (
        <TooltipProvider delayDuration={TOOLTIP_DELAY_MS}>
        <div
            className={cn(
                'relative col-span-12 flex h-full flex-col justify-between p-4 lg:col-span-4 broker-slider-container',
                isGerencialOficioDetail
                    ? 'overflow-hidden rounded-2xl shadow-sm'
                    : 'rounded-sm border bg-boxdark shadow-default',
            )}
            style={isGerencialOficioDetail ? gerencialOficioSectionStyle : undefined}
        >
            <div className="absolute right-4 top-4 z-10">
                {isLocked && <LockedSectionTooltip />}
            </div>

            {/* Overlay de vidro esfumaçado quando não há proposta vigente */}
            {!sliderData && (
                <div className="absolute inset-0 z-20 flex flex-col items-center justify-center gap-3 rounded-sm backdrop-blur-md bg-white/55 dark:bg-slate-900/65">
                    <div className="flex h-12 w-12 items-center justify-center rounded-full bg-white shadow-md dark:bg-slate-800">
                        <PlusCircle className="h-6 w-6 text-primary" />
                    </div>
                    <p className="text-sm font-semibold text-subtitle">Nenhuma proposta vigente</p>
                    <Button
                        variant="outline-default"
                        disabled={createProposalMutation.isPending}
                        onClick={() => createProposalMutation.mutate()}
                        className="h-8 gap-2 px-4 text-sm create-proposal-button"
                    >
                        {createProposalMutation.isPending ? (
                            <LoaderCircle size={14} className="animate-spin" />
                        ) : (
                            <PlusCircle size={14} />
                        )}
                        Criar Proposta
                    </Button>
                </div>
            )}

            <div
                className={cn(
                    'flex h-full flex-col justify-between broker-slider-container',
                    isLocked && !isSemSmartblock && 'pointer-events-none opacity-50',
                )}
            >
                <h2 className="mb-6 text-lg font-semibold text-subtitle">Proposta X Comissão</h2>

                {sliderData && isSemSmartblock && (
                    <SemSmartblockAlert className="mb-4 zero-proposal-banner" />
                )}

                <div className="relative flex h-full flex-1 flex-col justify-between">
                    {isSemSmartblock && <SemSmartblockSliderFrost className="rounded-lg" />}

                    <div
                        className={cn(
                            'flex h-full flex-1 flex-col justify-between',
                            isSliderInteractionLocked && 'pointer-events-none select-none',
                        )}
                    >
                    <div className="relative mb-6 flex flex-col gap-4">
                        <div className="flex w-full items-center justify-between gap-5 2xsm:flex-col">
                            <div className="flex w-full flex-1 flex-col gap-3">
                                <div className="flex w-full items-center justify-between text-sm">
                                    <p className="font-medium text-title">Proposta:</p>
                                    <div className="flex items-center gap-1 rounded-xl border border-blue-300/60 bg-white px-3 py-1.5 shadow-xs focus-within:border-blue-500 focus-within:ring-2 focus-within:ring-blue-500/20 dark:border-blue-800/80 dark:bg-slate-900">
                                        <span className="font-mono text-xs font-bold text-blue-600/70 dark:text-blue-400/70">
                                            R$
                                        </span>
                                        <input
                                            ref={proposalRef}
                                            type="text"
                                            onBlur={(e) => {
                                                e.target.value = formatCurrency(e.target.value);
                                            }}
                                            onChange={(e) =>
                                                changeInputValues('proposal', e.target.value)
                                            }
                                            className="w-32 border-none bg-transparent p-0 text-right font-mono text-sm font-bold text-blue-700 outline-none focus:ring-0 dark:text-blue-300"
                                        />
                                    </div>
                                </div>
                                <div className="flex w-full items-center justify-between gap-2 text-xs font-medium text-paragraph font-mono">
                                    <span>Min: {numberFormat(minProposal || 0)}</span>
                                    {isLocalhost && suggestedProposal > 0 && maxProposal > minProposal && (
                                        <Tooltip>
                                            <TooltipTrigger asChild>
                                                <button
                                                    type="button"
                                                    onClick={() => handleProposalSliderChange(suggestedProposal.toString(), true)}
                                                    className="inline-flex items-center gap-1 rounded-full border border-amber-500/30 bg-amber-500/10 px-2 py-0.5 text-[10px] font-bold font-mono text-amber-600 dark:text-amber-400 hover:bg-amber-500/20 transition-all cursor-pointer"
                                                >
                                                    <Sparkles className="h-2.5 w-2.5" />
                                                    Sugerido: {numberFormat(suggestedProposal)}
                                                </button>
                                            </TooltipTrigger>
                                            <TooltipContent side="top" sideOffset={6} className="pointer-events-none">
                                                <p className="text-xs">Clique para aplicar a sugestão histórica do SmartBlock</p>
                                            </TooltipContent>
                                        </Tooltip>
                                    )}
                                    <span>Máx: {numberFormat(maxProposal || 0)}</span>
                                </div>
                                <div className="relative w-full py-1">
                                    <input
                                        type="range"
                                        step={SLIDER_STEP}
                                        min={minProposal || 0}
                                        max={maxProposal || 0}
                                        value={sliderValues.proposal}
                                        onChange={(e) => {
                                            handleProposalSliderChange(e.target.value, true);
                                        }}
                                        className="range-slider w-full cursor-pointer"
                                    />
                                    {isLocalhost && suggestedProposal > 0 && maxProposal > minProposal && (
                                        <div
                                            className="absolute top-1/2 h-5 w-[2px] -translate-y-1/2 -translate-x-1/2 rounded-full bg-emerald-500 shadow-xs pointer-events-none z-10"
                                            style={{ left: getSliderThumbOffsetStyle(proposalSuggestionPct) }}
                                        />
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="my-1 h-px w-full bg-stroke dark:bg-form-strokedark sm:hidden"></div>

                        <div className="flex w-full items-center justify-between gap-5 2xsm:flex-col">
                            <div className="flex w-full flex-1 flex-col gap-3">
                                <div className="flex w-full items-center justify-between text-sm">
                                    <p className="font-medium text-title">Comissão:</p>
                                    <div className="flex items-center gap-1 rounded-xl border border-emerald-300/60 bg-white px-3 py-1.5 shadow-xs focus-within:border-emerald-500 focus-within:ring-2 focus-within:ring-emerald-500/20 dark:border-emerald-800/80 dark:bg-slate-900">
                                        <span className="font-mono text-xs font-bold text-emerald-600/70 dark:text-emerald-400/70">
                                            R$
                                        </span>
                                        <input
                                            ref={commissionBrokerRef}
                                            type="text"
                                            onBlur={(e) => {
                                                e.target.value = formatCurrency(e.target.value);
                                            }}
                                            onChange={(e) =>
                                                changeInputValues('commissionBroker', e.target.value)
                                            }
                                            className="w-32 border-none bg-transparent p-0 text-right font-mono text-sm font-bold text-emerald-700 outline-none focus:ring-0 dark:text-emerald-300"
                                        />
                                    </div>
                                </div>
                                <div className="flex w-full items-center justify-between gap-2 text-xs font-medium text-paragraph font-mono">
                                    <span>Min: {numberFormat(commissionSliderBounds.min || 0)}</span>
                                    {isLocalhost && suggestedBrokerCommission > 0 && commissionSliderBounds.max > commissionSliderBounds.min && (
                                        <Tooltip>
                                            <TooltipTrigger asChild>
                                                <button
                                                    type="button"
                                                    onClick={() => handleProposalSliderChange(suggestedProposal.toString(), true)}
                                                    className="inline-flex items-center gap-1 rounded-full border border-amber-500/30 bg-amber-500/10 px-2 py-0.5 text-[10px] font-bold font-mono text-amber-600 dark:text-amber-400 hover:bg-amber-500/20 transition-all cursor-pointer"
                                                >
                                                    <Sparkles className="h-2.5 w-2.5" />
                                                    Sugerido: {numberFormat(suggestedBrokerCommission)}
                                                </button>
                                            </TooltipTrigger>
                                            <TooltipContent side="top" sideOffset={6} className="pointer-events-none">
                                                <p className="text-xs">Comissão proporcional correspondente à proposta sugerida.</p>
                                            </TooltipContent>
                                        </Tooltip>
                                    )}
                                    <span>Máx: {numberFormat(commissionSliderBounds.max || 0)}</span>
                                </div>
                                <div className="relative w-full py-1">
                                    <input
                                        type="range"
                                        step={SLIDER_STEP}
                                        min={commissionSliderBounds.min || 0}
                                        max={commissionSliderBounds.max || 0}
                                        value={sliderValues.commissionBroker}
                                        onChange={(e) =>
                                            handleComissionBrokerSliderChange(e.target.value, true)
                                        }
                                        className="range-slider-reverse w-full cursor-pointer"
                                    />
                                    {isLocalhost && suggestedBrokerCommission > 0 && commissionSliderBounds.max > commissionSliderBounds.min && (
                                        <div
                                            className="absolute top-1/2 h-5 w-[2px] -translate-y-1/2 -translate-x-1/2 rounded-full bg-emerald-500 shadow-xs pointer-events-none z-10"
                                            style={{ left: getSliderThumbOffsetStyle(commissionSuggestionPct) }}
                                        />
                                    )}
                                </div>
                            </div>
                        </div>
                        {errorMessage && (
                            <p className="absolute -bottom-2 w-full text-center text-xs font-medium text-red">
                                Valor&#40;res&#41; fora do escopo definido
                            </p>
                        )}
                    </div>

                    <div className="flex gap-2">
                        <Button
                            variant="outline-default"
                            disabled={
                                isSemSmartblock ||
                                isProposalButtonDisabled.current ||
                                savingProposalAndComission ||
                                isSaveButtonDisabled
                            }
                            isLoading={savingProposalAndComission}
                            onClick={handleProposalAndCommission}
                            className="h-8 w-full rounded-[40px] border border-blue-200 bg-background px-2 text-sm font-medium text-blue-600 transition-all duration-300 hover:bg-blue-50 disabled:cursor-not-allowed disabled:opacity-50"
                        >
                            {'Salvar Oferta'}
                        </Button>
                        <div className="w-full">
                            <BrokerProposalWizard
                                extratoId={extratoId}
                                brandKitOwnerUserId={brandKitOwnerUserId}
                                buttonLabel="Gerar Proposta"
                                buttonClassName="!h-8 w-full px-2"
                                buttonDisabled={!maxProposal || isSemSmartblock}
                                offerValue={sliderValues.proposal}
                                offerCommission={sliderValues.commissionBroker}
                                onOfferChange={(value) => {
                                    if (proposalRef.current) {
                                        proposalRef.current.value = numberFormat(value);
                                    }
                                    handleProposalSliderChange(String(value), true);
                                }}
                            />
                        </div>
                    </div>
                    </div>
                </div>
            </div>
        </div>
        </TooltipProvider>
    );
};

export default BrokerSlider;

